  1→#!/usr/bin/env node
  2→
  3→/**
  4→ * update_docs.js
  5→ *
  6→ * Fetches the latest Claude Code documentation from docs.claude.com
  7→ * and saves it to the references/ directory.
  8→ *
  9→ * Usage: node scripts/update_docs.js
 10→ */
 11→
 12→const https = require('https');
 13→const fs = require('fs');
 14→const path = require('path');
 15→
 16→const LLMS_TXT_URL = 'https://docs.claude.com/llms.txt';
 17→const CLAUDE_CODE_PATTERN = /https:\/\/docs\.claude\.com\/en\/docs\/claude-code\/[^\s)]+\.md/g;
 18→const REFERENCES_DIR = path.join(__dirname, '..', 'references');
 19→
 20→/**
 21→ * Fetch content from a URL using https module
 22→ */
 23→function fetchUrl(url) {
 24→  return new Promise((resolve, reject) => {
 25→    https.get(url, (res) => {
 26→      let data = '';
 27→      res.on('data', (chunk) => data += chunk);
 28→      res.on('end', () => {
 29→        if (res.statusCode >= 200 && res.statusCode < 300) {
 30→          resolve(data);
 31→        } else {
 32→          reject(new Error(`HTTP ${res.statusCode}: ${res.statusMessage}`));
 33→        }
 34→      });
 35→    }).on('error', reject);
 36→  });
 37→}
 38→
 39→/**
 40→ * Extract Claude Code doc URLs from llms.txt
 41→ */
 42→async function getClaudeCodeUrls() {
 43→  console.log('📥 Fetching llms.txt...');
 44→  const content = await fetchUrl(LLMS_TXT_URL);
 45→
 46→  const urls = new Set();
 47→  const matches = content.matchAll(CLAUDE_CODE_PATTERN);
 48→
 49→  for (const match of matches) {
 50→    urls.add(match[0]);
 51→  }
 52→
 53→  return Array.from(urls).sort();
 54→}
 55→
 56→/**
 57→ * Fetch and save a single documentation page
 58→ */
 59→async function fetchAndSaveDoc(url) {
 60→  const filename = path.basename(url);
 61→  const filepath = path.join(REFERENCES_DIR, filename);
 62→
 63→  try {
 64→    console.log(`  Fetching ${filename}...`);
 65→    const content = await fetchUrl(url);
 66→    fs.writeFileSync(filepath, content, 'utf8');
 67→    return { url, filename, success: true };
 68→  } catch (error) {
 69→    console.error(`  ❌ Failed to fetch ${filename}: ${error.message}`);
 70→    return { url, filename, success: false, error: error.message };
 71→  }
 72→}
 73→
 74→/**
 75→ * Main execution
 76→ */
 77→async function main() {
 78→  console.log('🚀 Claude Code Documentation Updater\n');
 79→
 80→  // Ensure references directory exists
 81→  if (!fs.existsSync(REFERENCES_DIR)) {
 82→    fs.mkdirSync(REFERENCES_DIR, { recursive: true });
 83→  }
 84→
 85→  // Get all Claude Code documentation URLs
 86→  const urls = await getClaudeCodeUrls();
 87→  console.log(`✅ Found ${urls.length} Claude Code documentation pages\n`);
 88→
 89→  // Fetch all documentation pages
 90→  console.log('📥 Downloading documentation...');
 91→  const results = [];
 92→  for (const url of urls) {
 93→    const result = await fetchAndSaveDoc(url);
 94→    results.push(result);
 95→    // Small delay to be nice to the server
 96→    await new Promise(resolve => setTimeout(resolve, 100));
 97→  }
 98→
 99→  // Summary
100→  const successful = results.filter(r => r.success).length;
101→  const failed = results.filter(r => !r.success).length;
102→
103→  console.log(`\n✅ Documentation update complete!`);
104→  console.log(`   ${successful} files downloaded successfully`);
105→  if (failed > 0) {
106→    console.log(`   ${failed} files failed to download`);
107→  }
108→  console.log(`\n📁 Documentation saved to: ${REFERENCES_DIR}`);
109→}
110→
111→// Run if called directly
112→if (require.main === module) {
113→  main().catch(error => {
114→    console.error('❌ Error:', error.message);
115→    process.exit(1);
116→  });
117→}
118→
119→module.exports = { getClaudeCodeUrls, fetchAndSaveDoc };
